import{initialState,money,today,num,saveSupplier,deleteSupplier,archiveSupplier,saveRequest,submitRequest,decideApproval,createRfqFromRequest,recordQuotation,selectQuotation,createOrder,orderFromQuotation,createGrn,markGrnInventoryPosted,createBill,recordPayment,reversePayment,createReturn,markReturnInventoryPosted,supplierOutstanding,dashboardMetrics,REPORTS,reportRows,toCsv,documentTotals,uid}from"./core.js";import{createMovement,productStock,parseCsv}from"../inventory/core.js";
import{createWorkspaceStateStorage,createWorkspaceStore}from"/supabase/workspace.js";const localStorage=await createWorkspaceStateStorage(),inventoryCloud=await createWorkspaceStore("inventory");
import{departmentSelectOptions,sharedDepartmentName}from"/administration-workspace/departments.js";
const KEY="infobridgeindia.purchases.v1",DB="InfoBridgeIndiaInventory";let state=load(),view=location.hash.slice(1)||"dashboard",query="",filters={status:"",supplier:"",warehouse:"",report:REPORTS[0]},inventory={db:null,settings:{},products:[],warehouses:[],movements:[]};const $=s=>document.querySelector(s),esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c])),date=v=>v?new Intl.DateTimeFormat("en-IN",{dateStyle:"medium"}).format(new Date(v)):"—";
function load(){try{const x=JSON.parse(localStorage.getItem(KEY));return x?.version===1?x:initialState()}catch{return initialState()}}function persist(s=state){state=s;localStorage.setItem(KEY,JSON.stringify(s));render()}function toast(m,t="success"){const e=document.createElement("div");e.className=`toast ${t}`;e.textContent=m;$("#purchase-toast").append(e);setTimeout(()=>e.remove(),3200)}const invAll=collection=>inventoryCloud.all(collection);async function invPutMany(collection,rows){for(const row of rows)await inventoryCloud.put(collection,row);return rows}
async function openInventory(){const [settings,products,warehouses,movements]=await Promise.all(["settings","products","warehouses","movements"].map(invAll));inventory={...inventory,settings:settings.find(x=>x.id==="app")||{},products:products.filter(x=>x.active!==false),warehouses:warehouses.filter(x=>x.active!==false),movements};render()}
const NAV=[["dashboard","Dashboard"],["suppliers","Suppliers"],["requests","Purchase Requests"],["rfqs","RFQs"],["comparison","Quotation Comparison"],["orders","Purchase Orders"],["grns","Goods Receipts / GRN"],["bills","Purchase Bills"],["payments","Payments"],["returns","Purchase Returns"],["debits","Debit Notes"],["approvals","Approvals"],["reports","Reports"],["import","Import / Export"],["settings","Settings & Privacy"]];const PATH={dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',suppliers:'<circle cx="9" cy="8" r="4"/><path d="M3 21v-2a6 6 0 0112 0v2M16 11h5"/>',requests:'<path d="M6 3h12v18H6zM9 8h6M9 12h6M9 16h4"/>',rfqs:'<path d="M4 5h16v14H4zM4 9h16M8 13h4"/>',comparison:'<path d="M5 4v16M12 4v16M19 4v16M3 8h18M3 16h18"/>',orders:'<path d="M5 4h14v16H5zM8 8h8M8 12h8M8 16h5"/>',grns:'<path d="M4 7l8-4 8 4-8 4-8-4zM4 7v10l8 4 8-4V7M12 11v10"/>',bills:'<path d="M6 3h12v18l-3-2-3 2-3-2-3 2zM9 8h6M9 12h6"/>',payments:'<rect x="3" y="6" width="18" height="13" rx="2"/><path d="M3 10h18M7 15h3"/>',returns:'<path d="M9 7H5V3M5 7a8 8 0 101 10"/>',debits:'<path d="M5 4h14v16H5zM8 9h8M8 13h5"/>',approvals:'<path d="M5 13l4 4L19 7"/>',reports:'<path d="M4 20V4M4 20h16M8 16v4M12 11v9M16 7v13M20 3v17"/>',import:'<path d="M12 3v12M8 11l4 4 4-4M4 20h16"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M19 12a7 7 0 00-.1-1l2-2-2-3-3 1a8 8 0 00-2-1l-1-3h-3l-1 3a8 8 0 00-2 1L5 6 3 9l2 2a7 7 0 000 2l-2 2 2 3 3-1a8 8 0 002 1l1 3h3l1-3a8 8 0 002-1l3 1 2-3-2-2a7 7 0 000-1z"/>',search:'<circle cx="11" cy="11" r="7"/><path d="M16 16l5 5"/>',plus:'<path d="M12 5v14M5 12h14"/>',menu:'<path d="M4 7h16M4 12h16M4 17h16"/>'};function icon(n){return`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${PATH[n]||PATH.requests}</svg>`}
function shell(body){return`<div class="app-shell"><aside class="sidebar" id="sidebar"><a class="sidebar-brand" href="/index.html"><img src="/infobridgeindia-logo.png" alt="InfoBridgeIndia"></a><div class="workspace-label"><strong>Purchases & Procurement</strong><span>${esc(state.settings.branch)}</span></div><nav>${NAV.map(([v,l])=>`<button class="nav-link ${view===v?"active":""}" data-view="${v}">${icon(v)}<span>${l}</span></button>`).join("")}</nav><div class="local-note">Local-first database<br><span>Last saved automatically</span><a href="/index.html">Exit to website</a></div></aside><main class="main"><header class="topbar"><button class="icon-button mobile-menu" data-menu>${icon("menu")}</button><div class="global-search">${icon("search")}<input data-search value="${esc(query)}" placeholder="Search supplier, PO, GRN, bill…"></div><div class="top-actions"><button class="btn secondary compact" data-new="request">New Request</button><button class="btn primary compact" data-new="order">${icon("plus")} Create PO</button></div></header><div class="content">${body}</div><nav class="mobile-nav">${NAV.slice(0,5).map(([v,l])=>`<button class="${view===v?"active":""}" data-view="${v}">${icon(v)}<span>${l}</span></button>`).join("")}</nav></main></div>`}const head=(t,d,a="")=>`<div class="page-head"><div><h1>${t}</h1><p>${d}</p></div><div class="page-actions">${a}</div></div>`,metric=(l,v)=>`<div class="metric"><span>${l}</span><strong>${v}</strong></div>`,badge=s=>`<span class="badge ${["Approved","Paid","Confirmed","Fully Received","Active","Recorded","Selected"].includes(s)?"success":["Rejected","Cancelled","Overdue","Inactive","Reversed"].includes(s)?"danger":["Pending","Pending Approval","Partially Paid","Partially Received","Urgent"].includes(s)?"warn":"neutral"}">${esc(s||"—")}</span>`;function empty(t,d){return`<div class="empty"><div class="empty-icon">${icon("requests")}</div><h3>${t}</h3><p>${d}</p></div>`}function table(h,r){return`<div class="table-wrap"><table><thead><tr>${h.map(x=>`<th>${x}</th>`).join("")}</tr></thead><tbody>${r.join("")}</tbody></table></div>`}function filtered(rows,keys){const q=query.toLowerCase();return rows.filter(x=>(!q||keys.some(k=>String(x[k]||"").toLowerCase().includes(q)))&&(!filters.status||x.status===filters.status)&&(!filters.supplier||x.supplierId===filters.supplier)&&(!filters.warehouse||x.warehouseId===filters.warehouse))}function nameSup(id){return state.suppliers.find(x=>x.id===id)?.name||"Unknown supplier"}function nameProd(id){return inventory.products.find(x=>x.id===id)?.name||id||"Unknown item"}function nameWh(id){return inventory.warehouses.find(x=>x.id===id)?.name||id||"Unknown warehouse"}
function dashboard(){const m=dashboardMetrics(state),recent=state.requests.slice(0,5),pending=state.approvals.filter(x=>x.status==="Pending").slice(0,5),deliveries=state.orders.filter(x=>!["Fully Received","Closed","Cancelled"].includes(x.status)).slice(0,5),overdue=state.bills.filter(x=>x.balanceDue>0&&x.dueDate<today()),months=[...Array(6)].map((_,i)=>{const d=new Date();d.setMonth(d.getMonth()-5+i);const k=d.toISOString().slice(0,7);return{l:d.toLocaleString("en",{month:"short"}),v:state.bills.filter(x=>x.postingDate?.startsWith(k)).reduce((a,x)=>a+x.grandTotal,0)}}),mx=Math.max(1,...months.map(x=>x.v));return`${head("Purchase dashboard","Live totals calculated from saved procurement records.")}<div class="metrics">${metric("Pending Requests",m.pendingRequests)}${metric("Awaiting Approval",m.awaitingApproval)}${metric("Open RFQs",m.openRfqs)}${metric("Purchase Orders",m.purchaseOrders)}${metric("Pending Deliveries",m.pendingDeliveries)}${metric("Partially Received",m.partialOrders)}${metric("Bills Pending",m.billsPending)}${metric("Overdue Bills",m.overdueBills)}${metric("Month Purchases",money(m.monthPurchases))}${metric("Month Paid",money(m.monthPaid))}${metric("Supplier Outstanding",money(m.outstanding))}${metric("Purchase Returns",m.returns)}</div><div class="quick-card"><div><h2>Daily actions</h2><p>Every stage preserves supplier, item, tax, warehouse, and source references.</p></div><div class="quick-actions">${[["request","New Purchase Request"],["rfq","Create RFQ"],["order","Create Purchase Order"],["grn","Record GRN"],["bill","Add Purchase Bill"],["payment","Record Payment"],["return","Purchase Return"]].map(([a,l])=>`<button class="action-chip" data-new="${a}">${l}</button>`).join("")}</div></div><div class="proc-grid"><section class="panel span8"><div class="panel-head"><h2>Recent purchase requests</h2></div>${recent.length?requestTable(recent):empty("No purchase requests","Create a request to start procurement.")}</section><section class="panel span4"><div class="panel-head"><h2>Pending approvals</h2></div>${pending.length?table(["Type","Record"],pending.map(x=>`<tr><td>${esc(x.type)}</td><td>${esc(x.recordId)}</td></tr>`)):empty("Nothing pending","Submitted approvals appear here.")}</section><section class="panel span8"><div class="panel-head"><h2>Monthly purchases</h2></div><div class="chart">${months.map(x=>`<div class="bar" title="${money(x.v)}" style="height:${Math.max(2,x.v/mx*100)}%"><span>${x.l}</span></div>`).join("")}</div></section><section class="panel span4"><div class="panel-head"><h2>Expected deliveries</h2></div>${deliveries.length?table(["PO","Due"],deliveries.map(x=>`<tr><td>${esc(x.id)}<small>${esc(nameSup(x.supplierId))}</small></td><td>${date(x.expectedDeliveryDate)}</td></tr>`)):empty("No deliveries","Open purchase orders appear here.")}</section><section class="panel span8"><div class="panel-head"><h2>Recent purchase orders</h2></div>${state.orders.length?orderTable(state.orders.slice(0,5)):empty("No purchase orders","Create an approved order.")}</section><section class="panel span4"><div class="panel-head"><h2>Overdue supplier payments</h2></div>${overdue.length?table(["Bill","Balance"],overdue.map(x=>`<tr><td>${esc(x.id)}<small>${nameSup(x.supplierId)}</small></td><td class="num">${money(x.balanceDue)}</td></tr>`)):empty("Nothing overdue","Overdue bills appear here.")}</section></div>`}
function filterbar(statuses=[]){return`<div class="filters"><input data-filter-search value="${esc(query)}" placeholder="Search"><select data-filter="status"><option value="">All statuses</option>${statuses.map(x=>`<option ${filters.status===x?"selected":""}>${x}</option>`).join("")}</select><select data-filter="supplier"><option value="">All suppliers</option>${state.suppliers.filter(x=>!x.archived).map(x=>`<option value="${x.id}" ${filters.supplier===x.id?"selected":""}>${esc(x.name)}</option>`).join("")}</select><select data-filter="warehouse"><option value="">All warehouses</option>${inventory.warehouses.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join("")}</select></div>`}
function suppliers(){const rows=filtered(state.suppliers.filter(x=>!x.archived),["id","name","mobile","email","gstin"]);return`${head("Suppliers","Supplier master, purchase history, payments, and current outstanding.",`<button class="btn secondary" data-export="suppliers">Export</button><button class="btn primary" data-new="supplier">Add Supplier</button>`)}${filterbar(["Active","Inactive"])}<section class="panel">${rows.length?table(["Supplier","Contact","GSTIN","Terms","Purchases","Paid","Outstanding","Status","Actions"],rows.map(x=>{const purchases=state.bills.filter(b=>b.supplierId===x.id).reduce((a,b)=>a+b.grandTotal,0),paid=state.payments.filter(p=>p.supplierId===x.id&&p.status!=="Reversed").reduce((a,p)=>a+p.amount,0);return`<tr><td><strong>${esc(x.name)}</strong><small>${esc(x.id)} ${x.duplicateWarning?`· <span class="warning">${esc(x.duplicateWarning)}</span>`:""}</small></td><td>${esc(x.mobile)}<small>${esc(x.email)}</small></td><td>${esc(x.gstin||"Unregistered")}</td><td>${x.creditPeriod||x.paymentTerms||0} days</td><td class="num">${money(purchases)}</td><td class="num">${money(paid)}</td><td class="num">${money(supplierOutstanding(state,x.id))}</td><td>${badge(x.active?"Active":"Inactive")}</td><td><button class="more" data-supplier="${x.id}">View</button><button class="more" data-edit-supplier="${x.id}">Edit</button><button class="more" data-archive-supplier="${x.id}">Archive</button><button class="more danger-text" data-delete-supplier="${x.id}">Delete</button></td></tr>`})):empty("No suppliers","Add a supplier to begin purchasing.")}</section>`}
function requestTable(rows){return table(["Request","Date","Department","Warehouse","Required by","Value","Priority","Status","Actions"],rows.map(x=>`<tr><td><strong>${esc(x.id)}</strong><small>${esc(x.requestedBy)}</small></td><td>${date(x.date)}</td><td>${esc(x.department)}</td><td>${esc(nameWh(x.warehouseId))}</td><td>${date(x.requiredBy)}</td><td class="num">${money(x.items.reduce((a,i)=>a+i.quantity*i.estimatedRate,0))}</td><td>${badge(x.priority)}</td><td>${badge(x.status)}</td><td>${x.status==="Draft"?`<button class="more" data-submit-request="${x.id}">Submit</button>`:""}${["Approved","Partially Approved"].includes(x.status)&&!x.rfqId?`<button class="more" data-request-rfq="${x.id}">Create RFQ</button>`:""}</td></tr>`))}function requests(){const rows=filtered(state.requests,["id","requestedBy","department","status"]);return`${head("Purchase Requests","Request, approve, and convert required items.",`<button class="btn primary" data-new="request">New Purchase Request</button>`)}${filterbar(["Draft","Pending Approval","Approved","Partially Approved","Rejected","Converted","Cancelled"])}<section class="panel">${rows.length?requestTable(rows):empty("No purchase requests","Create the first internal requirement.")}</section>`}
function rfqs(){const rows=filtered(state.rfqs,["id","status","notes"]);return`${head("Requests for quotation","Send approved requirements to multiple suppliers and record responses.",`<button class="btn primary" data-new="rfq">Create RFQ</button>`)}${filterbar(["Draft","Sent","Partially Responded","Comparison Ready","Closed","Cancelled"])}<section class="panel">${rows.length?table(["RFQ","Dates","Warehouse","Suppliers","Responses","Status","Actions"],rows.map(x=>`<tr><td><strong>${x.id}</strong><small>${esc(x.requestId||"Manual")}</small></td><td>${date(x.date)}<small>Closes ${date(x.closingDate)}</small></td><td>${nameWh(x.warehouseId)}</td><td>${x.supplierIds.length}</td><td>${x.responses?.length||0}/${x.supplierIds.length}</td><td>${badge(x.status)}</td><td><button class="more" data-response="${x.id}">Add response</button><button class="more" data-print="${x.id}">Print</button></td></tr>`)):empty("No RFQs","Convert an approved request or create one.")}</section>`}
function comparison(){const rfqs=state.rfqs.filter(x=>x.responses?.length),selected=filters.rfq||rfqs[0]?.id,rows=state.quotations.filter(x=>x.rfqId===selected),low=Math.min(...rows.map(x=>x.landedCost));return`${head("Quotation comparison","Compare landed cost and delivery terms; supplier selection remains a user decision.")}<div class="filters"><select data-rfq>${rfqs.map(x=>`<option ${x.id===selected?"selected":""}>${x.id}</option>`).join("")}</select></div><section class="panel">${rows.length?table(["Supplier","Basic","Discount","Taxable","GST","Freight","Other","Landed cost","Delivery","Terms","Selection"],rows.map(x=>`<tr class="${x.landedCost===low?"comparison-low":""}"><td><strong>${esc(nameSup(x.supplierId))}</strong>${x.landedCost===low?"<small>Lowest landed cost</small>":""}</td><td>${money(x.items.reduce((a,i)=>a+i.quantity*i.rate,0))}</td><td>${money(x.items.reduce((a,i)=>a+i.quantity*i.rate*i.discount/100,0))}</td><td>${money(x.taxable)}</td><td>${money(x.cgst+x.sgst+x.igst)}</td><td>${money(x.freight)}</td><td>${money(x.otherCharges)}</td><td><strong>${money(x.landedCost)}</strong></td><td>${esc(x.deliveryPeriod||"—")}</td><td>${esc(x.paymentTerms||"—")}</td><td>${x.selected?badge("Selected"):`<button class="btn secondary compact" data-select-quote="${x.id}">Select</button>`}${x.selected&&!x.orderId?`<button class="more" data-quote-order="${x.id}">Create PO</button>`:""}</td></tr>`)):empty("No supplier responses","Record responses against an RFQ.")}</section>`}
function orderTable(rows){return table(["PO","Date","Supplier","Warehouse","Delivery","Total","Status","Actions"],rows.map(x=>`<tr><td><strong>${x.id}</strong><small>${esc(x.rfqId||"Manual")}</small></td><td>${date(x.date)}</td><td>${esc(nameSup(x.supplierId))}</td><td>${esc(nameWh(x.warehouseId))}</td><td>${date(x.expectedDeliveryDate)}</td><td class="num">${money(x.grandTotal)}</td><td>${badge(x.status)}</td><td><button class="more" data-print="${x.id}">Preview</button>${["Approved","Sent","Partially Received"].includes(x.status)?`<button class="more" data-po-grn="${x.id}">Create GRN</button>`:""}</td></tr>`))}function orders(){const rows=filtered(state.orders,["id","status"]);return`${head("Purchase Orders","Approved commitments with GST and received-quantity tracking.",`<button class="btn secondary" data-export="orders">Export</button><button class="btn primary" data-new="order">Create Purchase Order</button>`)}${filterbar(["Draft","Pending Approval","Approved","Sent","Partially Received","Fully Received","Closed","Cancelled"])}<section class="panel">${rows.length?orderTable(rows):empty("No purchase orders","Create manually or from a selected quotation.")}</section>`}
function grns(){return`${head("Goods Receipts / GRN","Accepted quantities post directly to the linked Inventory warehouse.",`<button class="btn primary" data-new="grn">Record GRN</button>`)}<section class="panel">${state.grns.length?table(["GRN","Date","PO","Supplier","Warehouse","Accepted","Damaged / Rejected","Inventory","Status"],state.grns.map(x=>`<tr><td><strong>${x.id}</strong></td><td>${date(x.date)}</td><td>${x.orderId}</td><td>${nameSup(x.supplierId)}</td><td>${nameWh(x.warehouseId)}</td><td>${x.items.reduce((a,i)=>a+i.acceptedQuantity,0)}</td><td>${x.items.reduce((a,i)=>a+i.damagedQuantity+i.rejectedQuantity,0)}</td><td>${badge(x.inventoryPosted?"Confirmed":"Pending")}</td><td>${badge(x.status)}</td></tr>`)):empty("No goods receipts","Receive an approved purchase order.")}</section>`}
function bills(){const rows=filtered(state.bills,["id","supplierInvoiceNumber","status"]);return`${head("Purchase Bills","Supplier invoices, PO/GRN mismatch checks, GST input, and payable balances.",`<button class="btn secondary" data-export="bills">Export</button><button class="btn primary" data-new="bill">Add Purchase Bill</button>`)}${filterbar(["Draft","Unpaid","Partially Paid","Paid","Overdue","Cancelled"])}<section class="panel">${rows.length?table(["Bill","Supplier invoice","Dates","Supplier","References","Taxable","GST","Total","Paid / Balance","Status"],rows.map(x=>`<tr><td><strong>${x.id}</strong></td><td>${esc(x.supplierInvoiceNumber)}</td><td>${date(x.invoiceDate)}<small>Due ${date(x.dueDate)}</small></td><td>${nameSup(x.supplierId)}</td><td>${esc(x.orderId||"—")}<small>${esc(x.grnId||"")}</small></td><td>${money(x.taxable)}</td><td>${money(x.cgst+x.sgst+x.igst)}</td><td><strong>${money(x.grandTotal)}</strong></td><td>${money(x.amountPaid)}<small>${money(x.balanceDue)} due</small></td><td>${badge(x.status)}${x.mismatches?.length?`<small class="warning">${x.mismatches.length} mismatch</small>`:""}</td></tr>`)):empty("No purchase bills","Add a supplier invoice from a PO/GRN or manually.")}</section>`}
function payments(){return`${head("Supplier Payments","Allocate partial or full payments and maintain accurate bill balances.",`<button class="btn primary" data-new="payment">Record Payment</button>`)}<section class="panel">${state.payments.length?table(["Voucher","Date","Supplier","Mode","Reference","Amount","Status","Actions"],state.payments.map(x=>`<tr><td>${x.id}</td><td>${date(x.date)}</td><td>${nameSup(x.supplierId)}</td><td>${x.mode}</td><td>${esc(x.reference||"—")}</td><td class="num">${money(x.amount)}</td><td>${badge(x.status)}</td><td>${x.status!=="Reversed"?`<button class="more danger-text" data-reverse="${x.id}">Reverse</button>`:""}</td></tr>`)):empty("No payments","Record a payment against open supplier bills.")}</section>`}
function returns(){return`${head("Purchase Returns","Return eligible received stock and create a linked debit note.",`<button class="btn primary" data-new="return">Purchase Return</button>`)}<section class="panel">${state.returns.length?table(["Return","Date","Supplier","GRN / Bill","Warehouse","Taxable","GST reversal","Total","Inventory"],state.returns.map(x=>`<tr><td>${x.id}</td><td>${date(x.date)}</td><td>${nameSup(x.supplierId)}</td><td>${esc(x.grnId||x.billId)}</td><td>${nameWh(x.warehouseId)}</td><td>${money(x.taxable)}</td><td>${money(x.cgst+x.sgst+x.igst)}</td><td>${money(x.grandTotal)}</td><td>${badge(x.inventoryPosted?"Confirmed":"Pending")}</td></tr>`)):empty("No purchase returns","Return stock against a GRN or bill.")}</section>`}function debits(){return`${head("Debit Notes","Supplier balance adjustments created from purchase returns.")}<section class="panel">${state.debitNotes.length?table(["Debit note","Date","Supplier","Bill","Return","Reason","Taxable","GST","Total","Status"],state.debitNotes.map(x=>`<tr><td>${x.id}</td><td>${date(x.date)}</td><td>${nameSup(x.supplierId)}</td><td>${esc(x.billId||"—")}</td><td>${esc(x.returnId||"—")}</td><td>${esc(x.reason)}</td><td>${money(x.taxable)}</td><td>${money(x.cgst+x.sgst+x.igst)}</td><td>${money(x.total)}</td><td>${badge(x.status)}</td></tr>`)):empty("No debit notes","A confirmed purchase return creates one automatically.")}</section>`}
function approvals(){return`${head("Approvals","Purchase request, purchase order, and mismatch approvals with traceable decisions.")}<section class="panel">${state.approvals.length?table(["Submitted","Type","Record","By","Level","Status","Decision","Comments"],state.approvals.map(x=>`<tr><td>${date(x.submittedAt)}</td><td>${x.type}</td><td>${x.recordId}</td><td>${esc(x.submittedBy)}</td><td>${x.level}</td><td>${badge(x.status)}</td><td>${x.status==="Pending"?`<button class="more" data-approve="${x.id}">Approve</button><button class="more danger-text" data-reject="${x.id}">Reject</button>`:date(x.decidedAt)}</td><td>${esc(x.comments||"—")}</td></tr>`)):empty("No approval history","Submitted documents appear here.")}</section>`}
function reports(){const rows=reportRows(state,filters.report);return`${head("Purchase reports","Saved-data reports with operational, payable, tax, and price history views.",`<button class="btn secondary" data-export-report>Export CSV</button>`)}<div class="filters"><select data-report>${REPORTS.map(x=>`<option ${x===filters.report?"selected":""}>${x}</option>`).join("")}</select><input type="date" data-from><input type="date" data-to><select data-filter="supplier"><option value="">All suppliers</option>${state.suppliers.map(x=>`<option value="${x.id}">${x.name}</option>`).join("")}</select></div><section class="panel"><div class="panel-head"><h2>${filters.report}</h2><strong>${rows.length} records</strong></div>${rows.length?genericTable(rows):empty("No report data","Complete procurement transactions to populate this report.")}</section>`}function genericTable(rows){const keys=[...new Set(rows.flatMap(Object.keys))].filter(k=>typeof rows[0]?.[k]!=="object").slice(0,9);return table(keys.map(x=>x.replace(/([A-Z])/g," $1")),rows.slice(0,100).map(r=>`<tr>${keys.map(k=>`<td>${typeof r[k]==="number"?money(r[k]):esc(r[k])}</td>`).join("")}</tr>`))}
function importExport(){return`${head("Import / Export","Validated supplier imports and procurement exports.")}<div class="two-col"><section class="panel padded"><span class="eyebrow">Supplier template</span><h2>Download CSV template</h2><p>Use the required columns, then preview and validate before importing.</p><button class="btn secondary" data-template>Download Supplier Template</button></section><section class="panel padded"><span class="eyebrow">Safe import</span><h2>Preview supplier CSV</h2><p>Invalid GSTINs and duplicate mobile, email, or GSTIN values are blocked.</p><label class="btn primary">Choose CSV<input hidden type="file" accept=".csv" data-import></label></section></div><section class="panel padded export-panel"><h2>Export procurement data</h2><div class="quick-actions">${["suppliers","requests","orders","bills","payments","returns"].map(x=>`<button class="action-chip" data-export="${x}">${x}</button>`).join("")}</div></section>`}function settings(){return`${head("Settings & Privacy","Company procurement defaults and approval controls.")}<section class="panel padded"><form data-settings class="form-grid">${field("company","Company",state.settings.company,true)}${field("branch","Branch",state.settings.branch,true)}${field("businessStateCode","Business state code",state.settings.businessStateCode,true)}${field("approvalLimit","PO approval limit","number",state.settings.approvalLimit,true,'min="0"')}<label class="toggle"><input type="checkbox" name="allowOverReceipt" ${state.settings.allowOverReceipt?"checked":""}> Allow authorised over-receipt</label><label class="toggle"><input type="checkbox" name="supplierAdvances" ${state.settings.supplierAdvances?"checked":""}> Allow supplier advances</label><button class="btn primary">Save Settings</button></form></section><section class="panel padded export-panel"><h2>Integration status</h2><p>${inventory.products.length} shared products · ${inventory.warehouses.length} shared warehouses · ${state.integration.gstPurchases.length} GST purchase records · ${state.integration.financeEntries.length} Finance-ready entries.</p></section>`}
function render(){const map={dashboard,suppliers,requests,rfqs,comparison,orders,grns,bills,payments,returns,debits,approvals,reports,import:importExport,settings};$("#purchase-app").innerHTML=shell((map[view]||dashboard)());bind()}
function field(n,l,t="text",v="",r=false,e=""){return`<label>${l}<input class="input" name="${n}" type="${t}" value="${esc(v)}" ${r?"required":""} ${e}></label>`}function select(n,l,opts,v="",r=false){return`<label>${l}<select class="input" name="${n}" ${r?"required":""}>${opts.map(x=>typeof x==="string"?`<option ${x===v?"selected":""}>${esc(x)}</option>`:`<option value="${x.id}" ${x.id===v?"selected":""}>${esc(x.name)}</option>`).join("")}</select></label>`}function modal(t,b,s,onSave,wide=true){$("#purchase-modal").innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?"wide":""}"><form><header><h2>${t}</h2><button type="button" class="icon-button" data-close>×</button></header><div class="modal-body">${b}</div><footer><button type="button" class="btn secondary" data-close>Cancel</button><button class="btn primary">${s}</button></footer></form></section></div>`;document.querySelectorAll("[data-close]").forEach(x=>x.onclick=()=>$("#purchase-modal").innerHTML="");$("#purchase-modal form").onsubmit=async e=>{e.preventDefault();try{await onSave(new FormData(e.target));$("#purchase-modal").innerHTML="";toast(`${t} saved.`)}catch(x){toast(x.message,"error")}}}
function supplierModal(x={}){modal(x.id?"Edit Supplier":"Add Supplier",`<div class="form-grid">${select("type","Supplier type",["Business","Individual"],x.type||"Business",true)}${field("name","Supplier / business name","text",x.name,true)}${field("contactPerson","Contact person","text",x.contactPerson)}${field("mobile","Mobile","tel",x.mobile,true)}${field("alternateMobile","Alternate mobile","tel",x.alternateMobile)}${field("email","Email","email",x.email)}${field("gstin","GSTIN","text",x.gstin)}${field("pan","PAN","text",x.pan)}${field("country","Country","text",x.country||"India")}${field("state","State","text",x.state)}${field("stateCode","State code","text",x.stateCode||state.settings.businessStateCode,true)}${field("city","City","text",x.city)}${field("pinCode","PIN code","text",x.pinCode)}${field("productsSupplied","Products / services supplied","text",x.productsSupplied)}${field("paymentTerms","Payment terms (days)","number",x.paymentTerms||30)}${field("creditPeriod","Credit period","number",x.creditPeriod||30)}${field("creditLimit","Credit limit","number",x.creditLimit||0)}${field("openingBalance","Opening balance","number",x.openingBalance||0)}${field("bankName","Bank name","text",x.bankName)}${field("accountHolder","Account holder","text",x.accountHolder)}${field("accountNumber","Account number","text",x.accountNumber)}${field("ifsc","IFSC","text",x.ifsc)}${field("upiId","UPI ID","text",x.upiId)}<label class="full">Billing address<textarea class="input" name="billingAddress">${esc(x.billingAddress)}</textarea></label><label class="full">Pickup / dispatch address<textarea class="input" name="dispatchAddress">${esc(x.dispatchAddress)}</textarea></label><label class="full">Notes<textarea class="input" name="notes">${esc(x.notes)}</textarea></label></div>`,"Save Supplier",fd=>persist(saveSupplier(state,{...x,...Object.fromEntries(fd),active:true}).state))}
function lineHtml(x={},estimate=false){return`<div class="line-grid"><select name="productId" required>${inventory.products.map(p=>`<option value="${p.id}" ${p.id===x.productId?"selected":""}>${esc(p.name)}</option>`).join("")}</select><input name="description" value="${esc(x.description||nameProd(x.productId))}" placeholder="Description"><input name="quantity" type="number" min=".001" step=".001" value="${num(x.quantity)||1}"><input name="unit" value="${esc(x.unit||"Nos")}" placeholder="Unit"><input name="${estimate?"estimatedRate":"rate"}" type="number" min="0" step=".01" value="${num(x[estimate?"estimatedRate":"rate"])}"><input name="gstRate" type="number" min="0" value="${num(x.gstRate)||18}"><button type="button" class="btn secondary" data-remove-line>×</button></div>`}function linesData(){return[...document.querySelectorAll("[data-lines] .line-grid")].map(r=>Object.fromEntries([...r.querySelectorAll("input,select")].map(e=>[e.name,e.value])))}function bindLines(estimate=false){const b=$("[data-lines]");$("[data-add-line]")?.addEventListener("click",()=>{b.insertAdjacentHTML("beforeend",lineHtml({},estimate));bindLines(estimate)});document.querySelectorAll("[data-remove-line]").forEach(x=>x.onclick=()=>{if(b.children.length>1)x.parentElement.remove()})}
function requestModal(){if(!inventory.products.length||!inventory.warehouses.length)return toast("Add Inventory products and a warehouse first.","error");modal("New Purchase Request",`<div class="form-grid">${field("date","Request date","date",today(),true)}${field("requestedBy","Requested by","text","Current User",true)}${select("departmentId","Department",departmentSelectOptions(),"",true)}${select("warehouseId","Warehouse",inventory.warehouses,"",true)}${field("requiredBy","Required by","date",today(),true)}${select("priority","Priority",["Low","Medium","High","Urgent"],"Medium")}${field("reason","Reason / purpose","text","",true)}</div><div class="lines"><div class="panel-head"><h2>Requested items</h2><button type="button" class="btn secondary compact" data-add-line>Add line</button></div><div data-lines>${lineHtml({},true)}</div></div><label>Notes<textarea class="input" name="notes"></textarea></label>`,"Save Draft",fd=>{const values=Object.fromEntries(fd);return persist(saveRequest(state,{...values,department:sharedDepartmentName(values.departmentId),items:linesData(),status:"Draft"}).state)});bindLines(true)}
function rfqModal(pr=null){const approved=state.requests.filter(x=>["Approved","Partially Approved"].includes(x.status)&&!x.rfqId),base=pr||approved[0];if(!base)return toast("Approve a purchase request first.","error");if(!state.suppliers.filter(x=>!x.archived).length)return toast("Add a supplier first.","error");modal("Create RFQ",`<div class="form-grid">${select("requestId","Approved request",approved.map(x=>({id:x.id,name:x.id})),base.id,true)}${field("date","RFQ date","date",today(),true)}${field("closingDate","Closing date","date",today(),true)}${field("requiredDeliveryDate","Required delivery","date",base.requiredBy,true)}</div><label>Suppliers<select class="input" name="supplierIds" multiple size="5" required>${state.suppliers.filter(x=>!x.archived).map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join("")}</select></label><label>Terms<textarea class="input" name="terms"></textarea></label>`,"Create RFQ",fd=>{const ids=[...$("[name=supplierIds]").selectedOptions].map(x=>x.value),r=createRfqFromRequest(state,fd.get("requestId"),{...Object.fromEntries(fd),supplierIds:ids});persist(r.state)})}
function responseModal(rfq){const pending=state.suppliers.filter(s=>rfq.supplierIds.includes(s.id)&&!state.quotations.some(q=>q.rfqId===rfq.id&&q.supplierId===s.id));if(!pending.length)return toast("All invited suppliers have responded.");modal("Supplier Quotation Response",`<div class="form-grid">${select("supplierId","Supplier",pending,"",true)}${field("supplierQuotationNumber","Supplier quotation no.","text","",true)}${field("date","Quotation date","date",today(),true)}${field("validUntil","Valid until","date",today(),true)}${field("deliveryPeriod","Delivery period","text")}${field("paymentTerms","Payment terms","text")}${field("freight","Freight","number",0)}${field("otherCharges","Other charges","number",0)}</div><div data-lines>${rfq.items.map(x=>lineHtml({...x,rate:x.estimatedRate})).join("")}</div>`,"Record Response",fd=>persist(recordQuotation(state,rfq.id,{...Object.fromEntries(fd),items:linesData()}).state));bindLines()}
function orderModal(base={}){if(!state.suppliers.length||!inventory.warehouses.length)return toast("Add a supplier and warehouse first.","error");modal("Create Purchase Order",`<div class="form-grid">${field("date","PO date","date",today(),true)}${select("supplierId","Supplier",state.suppliers.filter(x=>!x.archived),base.supplierId,true)}${select("warehouseId","Delivery warehouse",inventory.warehouses,base.warehouseId,true)}${field("expectedDeliveryDate","Expected delivery","date",today(),true)}${select("status","Status",["Draft","Pending Approval","Approved","Sent"],"Approved")}${field("placeOfSupply","Place of Supply code","text",state.suppliers.find(x=>x.id===base.supplierId)?.stateCode||state.settings.businessStateCode,true)}${field("freight","Freight","number",base.freight||0)}${field("otherCharges","Other charges","number",base.otherCharges||0)}${field("roundOff","Round-off","number",0)}</div><div class="lines"><div class="panel-head"><h2>Items</h2><button type="button" class="btn secondary compact" data-add-line>Add line</button></div><div data-lines>${(base.items?.length?base.items:[{}]).map(lineHtml).join("")}</div></div><label>Terms<textarea class="input" name="terms"></textarea></label>`,"Save Purchase Order",fd=>persist(createOrder(state,{...base,...Object.fromEntries(fd),items:linesData()}).state));bindLines()}
function grnModal(po=null){const orders=state.orders.filter(x=>["Approved","Sent","Partially Received"].includes(x.status)),base=po||orders[0];if(!base)return toast("No approved PO is pending receipt.","error");modal("Record Goods Receipt",`<div class="form-grid">${select("orderId","Purchase Order",orders.map(x=>({id:x.id,name:`${x.id} · ${nameSup(x.supplierId)}`})),base.id,true)}${field("date","GRN date","date",today(),true)}${field("deliveryNote","Delivery note / challan")}${field("supplierInvoiceReference","Supplier invoice reference")}${select("warehouseId","Receiving warehouse",inventory.warehouses,base.warehouseId,true)}${field("receivedBy","Received by","text","Current User",true)}</div><div class="return-lines">${base.items.map(i=>{const previous=state.grns.filter(g=>g.orderId===base.id).flatMap(g=>g.items).filter(x=>x.productId===i.productId).reduce((a,x)=>a+x.receivedQuantity,0),pending=i.quantity-previous;return`<div class="form-grid" data-grn-line data-product="${i.productId}"><strong>${esc(nameProd(i.productId))}<small>Ordered ${i.quantity} · previously ${previous} · pending ${pending}</small></strong>${field("receivedQuantity","Received","number",pending,true,'min="0" step=".001"')}${field("acceptedQuantity","Accepted","number",pending,true,'min="0" step=".001"')}${field("damagedQuantity","Damaged","number",0,false,'min="0"')}${field("rejectedQuantity","Rejected","number",0,false,'min="0"')}${field("batch","Batch")}${field("serial","Serial")}</div>`}).join("")}</div>`,"Confirm GRN",async fd=>{const items=[...document.querySelectorAll("[data-grn-line]")].map(r=>({productId:r.dataset.product,...Object.fromEntries([...r.querySelectorAll("input")].map(e=>[e.name,e.value]))})),result=createGrn(state,{...Object.fromEntries(fd),items}),prepared=[],history=[...inventory.movements];for(const i of result.record.items.filter(x=>x.acceptedQuantity>0)){const m=createMovement({type:"purchase-receipt",productId:i.productId,warehouseId:result.record.warehouseId,quantity:i.acceptedQuantity,unitCost:i.rate,reference:result.record.id,linkedId:result.record.orderId,notes:`PO ${result.record.orderId}; accepted quantity`},history,inventory.settings);prepared.push(m);history.push(m)}await invPutMany("movements",prepared);inventory.movements.push(...prepared);persist(markGrnInventoryPosted(result.state,result.record.id,prepared.map(x=>x.id)))})}
function billModal(){if(!state.suppliers.length)return toast("Add a supplier first.");const grn=state.grns[0],po=state.orders.find(x=>x.id===grn?.orderId),base=grn?{supplierId:grn.supplierId,grnId:grn.id,orderId:grn.orderId,items:grn.items.map(x=>({...x,quantity:x.acceptedQuantity}))}:po||{};modal("Add Purchase Bill",`<div class="form-grid">${select("supplierId","Supplier",state.suppliers,base.supplierId,true)}${field("supplierInvoiceNumber","Supplier invoice number","text","",true)}${field("invoiceDate","Supplier invoice date","date",today(),true)}${field("postingDate","Posting date","date",today(),true)}${field("dueDate","Due date","date",today(),true)}${field("orderId","PO reference","text",base.orderId||"")}${field("grnId","GRN reference","text",base.grnId||"")}${field("placeOfSupply","Place of Supply","text",state.suppliers.find(x=>x.id===base.supplierId)?.stateCode||state.settings.businessStateCode)}${field("freight","Freight","number",0)}${field("otherCharges","Other charges","number",0)}${field("roundOff","Round-off","number",0)}</div><div class="lines"><div class="panel-head"><h2>Bill items</h2><button type="button" class="btn secondary compact" data-add-line>Add line</button></div><div data-lines>${(base.items?.length?base.items:[{}]).map(lineHtml).join("")}</div></div><label class="toggle"><input type="checkbox" name="mismatchApproved"> Confirm authorised PO/GRN mismatch, if any</label>`,"Save Purchase Bill",fd=>persist(createBill(state,{...Object.fromEntries(fd),items:linesData(),mismatchApproved:fd.has("mismatchApproved")}).state));bindLines()}
function paymentModal(){const bills=state.bills.filter(x=>x.balanceDue>0&&x.status!=="Cancelled");if(!bills.length)return toast("No supplier bill is outstanding.");const supplier=state.suppliers.find(s=>bills.some(b=>b.supplierId===s.id));modal("Record Supplier Payment",`<div class="form-grid">${select("supplierId","Supplier",state.suppliers.filter(s=>bills.some(b=>b.supplierId===s.id)),supplier.id,true)}${field("date","Payment date","date",today(),true)}${select("mode","Payment mode",["Cash","Bank Transfer","UPI","Card","Cheque"],"Bank Transfer",true)}${field("bankAccount","Bank / account")}${field("reference","Reference number")}</div><div class="return-lines">${bills.filter(b=>b.supplierId===supplier.id).map(b=>`<label>${b.id} · outstanding ${money(b.balanceDue)}<input class="input" type="number" min="0" max="${b.balanceDue}" step=".01" value="0" data-allocation="${b.id}"></label>`).join("")}</div><label>Notes<textarea class="input" name="notes"></textarea></label>`,"Record Payment",fd=>{const allocations=[...document.querySelectorAll("[data-allocation]")].map(x=>({billId:x.dataset.allocation,amount:x.value}));persist(recordPayment(state,{...Object.fromEntries(fd),allocations}).state)})}
function returnModal(){const sources=state.grns.filter(x=>x.inventoryPosted);if(!sources.length)return toast("A confirmed, inventory-posted GRN is required.");const g=sources[0];modal("Purchase Return",`<div class="form-grid">${select("grnId","GRN",sources.map(x=>({id:x.id,name:x.id})),g.id,true)}${field("date","Return date","date",today(),true)}${field("reason","Return reason","text","",true)}${select("warehouseId","Return warehouse",inventory.warehouses,g.warehouseId,true)}</div><div class="return-lines">${g.items.filter(x=>x.acceptedQuantity>0).map(i=>`<label>${esc(nameProd(i.productId))} · received ${i.acceptedQuantity} · stock ${productStock(i.productId,inventory.movements,g.warehouseId)}<input class="input" type="number" min="0" max="${i.acceptedQuantity}" step=".001" value="0" data-return="${i.productId}"></label>`).join("")}</div>`,"Confirm Return",async fd=>{const items=[...document.querySelectorAll("[data-return]")].map(x=>({productId:x.dataset.return,quantity:x.value})),result=createReturn(state,{...Object.fromEntries(fd),supplierId:g.supplierId,billId:state.bills.find(b=>b.grnId===g.id)?.id,items}),prepared=[],history=[...inventory.movements];for(const i of result.record.items){const m=createMovement({type:"supplier-return",productId:i.productId,warehouseId:result.record.warehouseId,quantity:i.quantity,unitCost:i.rate,reference:result.record.id,linkedId:result.record.debitNoteId,reason:result.record.reason},history,inventory.settings);prepared.push(m);history.push(m)}await invPutMany("movements",prepared);inventory.movements.push(...prepared);persist(markReturnInventoryPosted(result.state,result.record.id,prepared.map(x=>x.id)))})}
function supplierProfile(id){const s=state.suppliers.find(x=>x.id===id),docs=[...state.orders,...state.grns,...state.bills,...state.payments,...state.returns,...state.debitNotes].filter(x=>x.supplierId===id);modal(s.name,`<div class="proc-grid"><div class="span4"><p><strong>${esc(s.mobile)}</strong><br>${esc(s.email||"—")}<br>${esc(s.gstin||"GST unregistered")}</p><p>${esc(s.billingAddress||"No address")}</p><h2>Outstanding ${money(supplierOutstanding(state,id))}</h2><a class="btn secondary" href="tel:${esc(s.mobile)}">Call</a> <a class="btn secondary" target="_blank" href="https://wa.me/${esc(s.mobile.replace(/\D/g,""))}">WhatsApp</a></div><div class="span8 timeline">${docs.map(x=>`<article><strong>${esc(x.id)}</strong><p>${esc(x.status)} · ${money(x.grandTotal||x.amount||x.total)}</p><small>${date(x.date||x.createdAt)}</small></article>`).join("")||"No history."}</div></div>`,"Close",()=>{})}
function exportKind(kind){const map={suppliers:state.suppliers,requests:state.requests,orders:state.orders,bills:state.bills,payments:state.payments,returns:state.returns};download(`${kind}.csv`,toCsv(map[kind]||[]))}function download(n,c){const a=document.createElement("a");a.href=URL.createObjectURL(new Blob(["\ufeff",c],{type:"text/csv"}));a.download=n;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}async function previewImport(file){const rows=parseCsv(await file.text()),validated=rows.map((r,i)=>{const errors=[];if(!r.Name)errors.push("Name required");if(!r.Mobile)errors.push("Mobile required");if(!r["State Code"])errors.push("State Code required");if(r.GSTIN&&!/^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z]$/i.test(r.GSTIN))errors.push("Invalid GSTIN");if(state.suppliers.some(s=>s.mobile===r.Mobile||r.GSTIN&&s.gstin===r.GSTIN))errors.push("Duplicate supplier");return{r,row:i+2,errors}});modal("Supplier Import Preview",`${table(["Row","Name","Mobile","GSTIN","Validation"],validated.map(x=>`<tr><td>${x.row}</td><td>${esc(x.r.Name)}</td><td>${esc(x.r.Mobile)}</td><td>${esc(x.r.GSTIN)}</td><td>${x.errors.length?`<span class="error-text">${x.errors.join(", ")}</span>`:'<span class="success-text">Ready</span>'}</td></tr>`))}`,"Import Suppliers",()=>{if(validated.some(x=>x.errors.length))throw Error("Fix row errors before importing");let s=state;for(const x of validated)s=saveSupplier(s,{type:x.r.Type||"Business",name:x.r.Name,mobile:x.r.Mobile,email:x.r.Email,gstin:x.r.GSTIN,stateCode:x.r["State Code"],active:true}).state;persist(s)})}
function bind(){document.querySelectorAll("[data-view]").forEach(x=>x.onclick=()=>{view=x.dataset.view;location.hash=view;$("#sidebar")?.classList.remove("open");render()});$("[data-menu]")?.addEventListener("click",()=>$("#sidebar").classList.toggle("open"));$("[data-search]")?.addEventListener("input",e=>{query=e.target.value;render()});$("[data-filter-search]")?.addEventListener("input",e=>{query=e.target.value;render()});document.querySelectorAll("[data-filter]").forEach(x=>x.onchange=()=>{filters[x.dataset.filter]=x.value;render()});document.querySelectorAll("[data-new]").forEach(x=>x.onclick=()=>({supplier:supplierModal,request:requestModal,rfq:rfqModal,order:orderModal,grn:grnModal,bill:billModal,payment:paymentModal,return:returnModal}[x.dataset.new]?.()));document.querySelectorAll("[data-edit-supplier]").forEach(x=>x.onclick=()=>supplierModal(state.suppliers.find(s=>s.id===x.dataset.editSupplier)));document.querySelectorAll("[data-supplier]").forEach(x=>x.onclick=()=>supplierProfile(x.dataset.supplier));document.querySelectorAll("[data-archive-supplier]").forEach(x=>x.onclick=()=>{if(confirm("Archive this supplier?"))persist(archiveSupplier(state,x.dataset.archiveSupplier))});document.querySelectorAll("[data-delete-supplier]").forEach(x=>x.onclick=()=>{if(confirm("Delete this unlinked supplier?"))try{persist(deleteSupplier(state,x.dataset.deleteSupplier))}catch(e){toast(e.message,"error")}});document.querySelectorAll("[data-submit-request]").forEach(x=>x.onclick=()=>persist(submitRequest(state,x.dataset.submitRequest)));document.querySelectorAll("[data-request-rfq]").forEach(x=>x.onclick=()=>rfqModal(state.requests.find(r=>r.id===x.dataset.requestRfq)));document.querySelectorAll("[data-response]").forEach(x=>x.onclick=()=>responseModal(state.rfqs.find(r=>r.id===x.dataset.response)));$("[data-rfq]")?.addEventListener("change",e=>{filters.rfq=e.target.value;render()});document.querySelectorAll("[data-select-quote]").forEach(x=>x.onclick=()=>{const q=state.quotations.find(v=>v.id===x.dataset.selectQuote),low=Math.min(...state.quotations.filter(v=>v.rfqId===q.rfqId).map(v=>v.landedCost)),note=q.landedCost>low?prompt("Reason for choosing a higher-priced supplier:")||"":"Lowest landed cost selected";try{persist(selectQuotation(state,q.id,note))}catch(e){toast(e.message,"error")}});document.querySelectorAll("[data-quote-order]").forEach(x=>x.onclick=()=>{const q=state.quotations.find(v=>v.id===x.dataset.quoteOrder),rfq=state.rfqs.find(v=>v.id===q.rfqId);try{persist(orderFromQuotation(state,q.id,{warehouseId:rfq.warehouseId,expectedDeliveryDate:rfq.requiredDeliveryDate}).state)}catch(e){toast(e.message,"error")}});document.querySelectorAll("[data-po-grn]").forEach(x=>x.onclick=()=>grnModal(state.orders.find(v=>v.id===x.dataset.poGrn)));document.querySelectorAll("[data-approve]").forEach(x=>x.onclick=()=>persist(decideApproval(state,x.dataset.approve,"Approved")));document.querySelectorAll("[data-reject]").forEach(x=>x.onclick=()=>{const reason=prompt("Rejection reason:");if(reason)persist(decideApproval(state,x.dataset.reject,"Rejected",{reason}))});document.querySelectorAll("[data-reverse]").forEach(x=>x.onclick=()=>{const r=prompt("Payment reversal reason:");if(r)persist(reversePayment(state,x.dataset.reverse,r))});document.querySelectorAll("[data-print]").forEach(x=>x.onclick=()=>window.print());document.querySelectorAll("[data-export]").forEach(x=>x.onclick=()=>exportKind(x.dataset.export));$("[data-report]")?.addEventListener("change",e=>{filters.report=e.target.value;render()});$("[data-export-report]")?.addEventListener("click",()=>download(`${filters.report}.csv`,toCsv(reportRows(state,filters.report))));$("[data-template]")?.addEventListener("click",()=>download("supplier-import-template.csv","Type,Name,Mobile,Email,GSTIN,State Code\r\n"));$("[data-import]")?.addEventListener("change",e=>previewImport(e.target.files[0]));$("[data-settings]")?.addEventListener("submit",e=>{e.preventDefault();const f=new FormData(e.target);state.settings={...state.settings,...Object.fromEntries(f),approvalLimit:num(f.get("approvalLimit")),allowOverReceipt:f.has("allowOverReceipt"),supplierAdvances:f.has("supplierAdvances")};persist(state);toast("Settings saved.")})}
render();openInventory().catch(e=>toast(`Inventory connection: ${e.message}`,"error"));
